<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import PagedList from './PagedList.vue'
import RichText from './RichText.vue'
export type DirectoryQuestion={id:string;course_id:string;section_id:string|null;question_type:string;stem:string;options:string[];correct_answer:string|null;explanation:string|null;difficulty:number;knowledge_point:string|null;retry_count?:number;wrong_count?:number;mastered?:boolean}
const props=defineProps<{request:(path:string,options?:RequestInit)=>Promise<unknown>;role:string;courses:{id:string;title:string;sections?:{id:string;title:string}[]}[];revision:number;wrong?:boolean}>()
const emit=defineEmits<{select:[item:DirectoryQuestion];create:[];assistant:[];compose:[]}>()
const course=ref(''),section=ref(''),difficulty=ref(''),kind=ref(''),keyword=ref(''),applied=ref(''),refresh=ref(0),mastery=ref('pending')
const selectedCourse=computed(()=>props.courses.find(x=>x.id===course.value)),scope=computed(()=>JSON.stringify([course.value,section.value,difficulty.value,kind.value,applied.value,refresh.value,mastery.value,props.revision]))
const items=computed<DirectoryQuestion[]>(()=>{void props.revision;return []})
const controller=new AbortController()
const types:Record<string,string>={single_choice:'单选题',multiple_choice:'多选题',true_false:'判断题',fill_blank:'填空题',short_answer:'简答题'}
const title=(id:string)=>props.courses.find(x=>x.id===id)?.title||'课程'
async function load(page:number,pageSize:number) {
  const params=new URLSearchParams({page:String(page),page_size:String(pageSize),keyword:applied.value})
  if(course.value)params.set(props.wrong?'scope_id':'course_id',course.value)
  if(props.wrong)params.set('mastery',mastery.value)
  if(!props.wrong){if(section.value)params.set('section_id',section.value);if(kind.value)params.set('question_type',kind.value);if(difficulty.value)params.set('difficulty',difficulty.value)}
  const result=await props.request(`${props.wrong?'/api/v1/paged/wrong-questions':'/api/v1/questions/page'}?${params}`,{signal:controller.signal}) as {items:any[];total:number;page:number;page_size:number}
  return props.wrong?{...result,items:result.items.map(x=>({...x.question,retry_count:x.retry_count,wrong_count:x.wrong_count,mastered:x.mastered}))}:result
}
watch(course,()=>section.value='')
onBeforeUnmount(()=>controller.abort())
</script>
<template>
  <section class="question-directory" :aria-label="wrong?'错题查询':'题库查询'"><header><div><h2>{{ wrong?'错题复习':role==='student'?'按知识点练习':'课程题库' }}</h2><p>{{ wrong?'重新作答，再看解析，逐步巩固薄弱知识。':role==='student'?'选择一道题开始练习，提交后查看解析与反馈。':'先浏览题目，点击查看完整题干、答案与解析。' }}</p></div><div v-if="role!=='student'" class="qd-actions"><button type="button" @click="emit('assistant')">✦ AI 辅助出题</button><button type="button" @click="emit('compose')">选题组卷</button><button type="button" class="primary" @click="emit('create')">＋ 新建题目</button></div></header>
    <form class="qd-filters" @submit.prevent="applied=keyword.trim();refresh++"><label>课程<select v-model="course"><option value="">全部课程</option><option v-for="item in courses" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label v-if="!wrong">章节<select v-model="section" :disabled="!course"><option value="">全部章节</option><option v-for="item in selectedCourse?.sections||[]" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label v-if="!wrong">题型<select v-model="kind"><option value="">全部题型</option><option v-for="(label,key) in types" :key="key" :value="key">{{ label }}</option></select></label><label v-if="!wrong">难度<select v-model="difficulty"><option value="">全部难度</option><option v-for="i in 5" :key="i" :value="i">{{ i }} 级</option></select></label><label v-if="wrong">巩固状态<select v-model="mastery"><option value="pending">待巩固</option><option value="mastered">已巩固</option><option value="all">全部记录</option></select></label><label class="qd-search">题干或知识点<input v-model="keyword" type="search" maxlength="100" placeholder="例如：二叉树、事务隔离" /></label><button type="submit">查询</button><button type="button" @click="course='';section='';kind='';difficulty='';keyword='';applied='';mastery='pending';refresh++">重置</button></form>
    <PagedList :items="items" :scope="scope" :load-page="load" :label="wrong?'错题复习':'题库练习'" v-slot="{items:rows,loading,error}"><button v-for="item in rows" :key="item.id" type="button" class="qd-row" @click="emit('select',item)"><span class="qd-question-icon">{{ wrong?'↻':'?' }}</span><span class="qd-content"><small>{{ title(item.course_id) }} <span v-if="wrong"> · {{ item.mastered?'已巩固':'待巩固' }} · 错误 {{ item.wrong_count }} 次</span></small><span class="qd-stem"><RichText :source="item.stem" :tools="false" /></span><span class="qd-tags"><b>{{ types[item.question_type] }}</b><span>{{ item.knowledge_point || '综合知识' }}</span><span>难度 {{ item.difficulty }}</span><span v-if="wrong">再练 {{ item.retry_count }} 次</span></span></span><span class="qd-action">{{ role==='student'?(wrong?'重新练习':'开始练习'):'查看详情' }} ›</span></button><p v-if="!rows.length&&!loading&&!error" class="qd-empty">{{ wrong?'当前没有符合条件的错题，可以到题库继续练习。':'暂无符合条件的题目，请调整筛选条件。' }}</p></PagedList>
  </section>
</template>
<style scoped>
.question-directory{background:white;border:1px solid #e1e9f4;border-radius:18px;padding:24px;color:#2b4667;min-width:0}.question-directory>header{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:20px}.question-directory h2{font-size:18px;margin:0 0 8px}.question-directory header p{font-size:12px;color:#8597ae;line-height:1.8;margin:0}.qd-actions{display:flex;gap:7px;flex-wrap:wrap}button{padding:10px 14px;font-size:12px;border:1px solid #dbe6f4;border-radius:9px;background:#edf3fc;color:#5077a8}.primary{background:#3576c9;color:white}.qd-filters{display:flex;flex-wrap:wrap;gap:10px;background:#f8fafd;padding:14px;border-radius:12px;align-items:end;margin-bottom:16px}.qd-filters label{display:grid;gap:7px;font-size:11px;color:#8296b0;flex:1;min-width:110px}.qd-filters label.qd-search{flex:2;min-width:180px}.qd-filters input,.qd-filters select{width:100%;min-width:0;box-sizing:border-box;border:1px solid #dce6f3;border-radius:9px;padding:10px;color:#365274;background:white;font-size:12px}.qd-row{display:flex;align-items:center;gap:17px;width:100%;padding:22px 0;text-align:left;background:white;border:0;border-bottom:1px solid #e9eff6;border-radius:0;color:#36516f}.qd-row:hover{background:#f9fbff}.qd-question-icon{display:grid;place-items:center;width:34px;height:38px;flex:none;background:#edf4ff;color:#6f94c6;font-size:20px;border-radius:9px}.qd-content{display:grid;gap:10px;flex:1;min-width:0}.qd-content>small{font-size:11px;color:#8b9db5;font-weight:400}.qd-stem{max-height:84px;overflow:hidden;display:block;font-weight:500}.qd-stem :deep(.rich-text){font-size:14px;line-height:1.8}.qd-stem :deep(p){margin:0}.qd-tags{display:flex;flex-wrap:wrap;gap:10px;font-size:11px;font-weight:400;color:#8a9bb1}.qd-tags b{font-size:10px;font-weight:400;color:#6089bc}.qd-action{font-size:12px;color:#487cbf;flex:none}.qd-empty{font-size:13px;color:#8a9ab0;text-align:center;padding:35px 0;line-height:1.9}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #afccef;outline-offset:2px}
@media(max-width:900px){.question-directory>header{flex-direction:column;align-items:start}}@media(max-width:650px){.question-directory{padding:16px}.question-directory h2{font-size:17px}.qd-filters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;padding:12px}.qd-filters label,.qd-filters label.qd-search{min-width:0}.qd-filters .qd-search{grid-column:1/-1}.qd-filters input,.qd-filters select{font-size:16px;padding:10px 8px}.qd-row{gap:11px;align-items:start;flex-wrap:wrap;padding:19px 0}.qd-question-icon{width:29px;height:32px;font-size:17px}.qd-content{flex-basis:75%}.qd-action{margin-left:auto;font-size:11px}.qd-tags{font-size:10px;gap:8px}.qd-stem :deep(.rich-text){font-size:13px}.qd-actions button{font-size:11px;padding:9px 10px}}
</style>
